function utilization(lambda, mu) {
  return lambda / mu;
}

function littleL(lambda, w) {
  return lambda * w;
}

function littleW(l, lambda) {
  return l / lambda;
}

function spareCapacity(lambda, mu) {
  return mu - lambda;
}

function isStable(lambda, mu) {
  return lambda < mu;
}

function throughput(lambda, mu) {
  return Math.min(lambda, mu);
}

function arrivalsFor(rho, mu) {
  return rho * mu;
}

function timeInSystem(lambda, mu) {
  if (lambda >= mu) throw new Error("unstable queue");
  return 1 / (mu - lambda);
}

function maxArrivalRate(mu, targetW) {
  return Math.max(0, mu - 1 / targetW);
}

function headroom(lambda, mu, maxUtilization) {
  if (lambda >= mu) return "unstable";
  if (lambda / mu > maxUtilization) return "too busy";
  return "ok";
}
